  6934  /*
  6935   * In order to be recognized as a `.mrb` file, the following three points must be satisfied:
  6936   * - File starts with "RITE"
  6937   * - At least `sizeof(struct rite_binary_header)` bytes can be read
  6938   * - `NUL` is included in the first 64 bytes of the file
  6939   */
  6940  MRB_API mrb_value
  6941  mrb_load_detect_file_cxt(mrb_state *mrb, FILE *fp, mrbc_context *c)
  6942  {
  6943    union {
  6944      char b[DETECT_SIZE];
  6945      struct rite_binary_header h;
  6946    } leading;
  6947    size_t bufsize;
  6948
  6949    if (mrb == NULL || fp == NULL) {
  6950      return mrb_nil_value();
  6951    }
  6952
  6953    bufsize = fread(leading.b, sizeof(char), sizeof(leading), fp);
  6954    if (bufsize < sizeof(leading.h) ||
  6955        memcmp(leading.h.binary_ident, RITE_BINARY_IDENT, sizeof(leading.h.binary_ident)) != 0 ||
  6956        memchr(leading.b, '\0', bufsize) == NULL) {
  6957      return mrb_load_exec(mrb, mrb_parse_file_continue(mrb, fp, leading.b, bufsize, c), c);
  6958    }
  6959    else {
  6960      mrb_int binsize;
  6961      uint8_t *bin;
  6962      mrb_value bin_obj = mrb_nil_value(); /* temporary string object */
  6963      mrb_value result;
  6964
  6965      binsize = bin_to_uint32(leading.h.binary_size);
  6966      bin_obj = mrb_str_new(mrb, NULL, binsize);
  6967      bin = (uint8_t*)RSTRING_PTR(bin_obj);
  6968      if ((size_t)binsize > bufsize)  {
  6969        memcpy(bin, leading.b, bufsize);
  6970        if (fread(bin + bufsize, binsize - bufsize, 1, fp) == 0) {
  6971          binsize = bufsize;
  6972          /* The error is reported by mrb_load_irep_buf_cxt() */
  6973        }
  6974      }
  6975
  6976      result = mrb_load_irep_buf_cxt(mrb, bin, binsize, c);
  6977      if (mrb_string_p(bin_obj)) mrb_str_resize(mrb, bin_obj, 0);
  6978      return result;
  6979    }
  6980  }
